func StartXML() {
	if g.XmlFilename != "-" {
		openedXmlFile = OpenFile(g.XmlFilename)
	}
	portsLen := 3846
	portsStr := shodanPortList
	if value, ok := g.Args["p"]; ok && value != "-" {
		portsLen = len(g.PortList)
		portsStr = value
	}
	startstr := ConvertTime(g.ScanStartTime, "nmap-file")
	command := xmlEscapeCommand(GetCommand())
	Write(fmt.Sprintf(`<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE nmaprun>
<?xml-stylesheet href="file:///usr/bin/../share/nmap/nmap.xsl" type="text/xsl"?>
<!-- Nmap 7.99 scan initiated %s as: %s -->
<nmaprun scanner="nmap" args="%s" start="%d" startstr="%s" version="7.99" xmloutputversion="1.05">
<scaninfo type="connect" protocol="tcp" numservices="%d" services="%s"/>
<verbose level="0"/>
<debugging level="0"/>
`, startstr, command, command, g.ScanStartTime.Unix(), startstr, portsLen, portsStr), g.XmlFilename, openedXmlFile)
}

func xmlEscapeText(value string) string {
	var buf bytes.Buffer
	_ = xml.EscapeText(&buf, []byte(value))
	return buf.String()
}

func xmlEscapeAttr(value string) string {
	escaped := xmlEscapeText(value)
	escaped = strings.ReplaceAll(escaped, "&#34;", "&quot;")
	escaped = strings.ReplaceAll(escaped, `"`, "&quot;")
	return escaped
}

func xmlEscapeCommand(value string) string {
	return strings.ReplaceAll(xmlEscapeAttr(value), "--", "-&#45;")
}

func scriptElementToXML(element g.ScriptElement) string {
	if element.Kind != "elem" && element.Kind != "table" {
		return ""
	}
	thisString := "<" + element.Kind
	if element.Key != "" {
		thisString += fmt.Sprintf(` key="%s"`, xmlEscapeAttr(element.Key))
	}
	thisString += ">"
	if element.Value != "" {
		thisString += xmlEscapeText(element.Value)
	}
	for _, child := range element.Elements {
		thisString += scriptElementToXML(child)
	}
	thisString += fmt.Sprintf("</%s>", element.Kind)
	return thisString
}

func scriptToXML(script g.Script) string {
	thisString := fmt.Sprintf(`<script id="%s"`, xmlEscapeAttr(script.ID))
	if script.Output != "" {
		thisString += fmt.Sprintf(` output="%s"`, xmlEscapeAttr(script.Output))
	}
	thisString += ">"
	for _, element := range script.Elements {
		thisString += scriptElementToXML(element)
	}
	thisString += "</script>"
	return thisString
}

func portToXML(port g.Port, result g.Output) string {
	thisString := fmt.Sprintf(`<port protocol="%s" portid="%d"><state state="open" reason="syn-ack" reason_ttl="0"/>`, port.Protocol, port.Port)
	if port.Service != "" {
		thisString += fmt.Sprintf(`<service name="%s"`, xmlEscapeAttr(strings.TrimSuffix(port.Service, "?")))
		if port.Product != "" {
			thisString += fmt.Sprintf(` product="%s"`, xmlEscapeAttr(port.Product))
		}
		if port.Version != "" {
			thisString += fmt.Sprintf(` version="%s"`, xmlEscapeAttr(port.Version))
		}
		if result.OS.Port == port.Port {
			thisString += fmt.Sprintf(` ostype="%s" method="probed" conf="8">`, xmlEscapeAttr(result.OS.Name))
		} else if port.ServiceSource == "port-default" || port.ServiceSource == "nmap-table" {
			thisString += ` method="table" conf="3">`
		} else {
			thisString += fmt.Sprintf(` method="probed" conf="%d">`, port.NmapConfidence)
		}
		for _, cpe := range port.Cpes {
			thisString += fmt.Sprintf(`<cpe>%s</cpe>`, xmlEscapeText(cpe))
		}
		thisString += "</service>"
	}
	for _, script := range port.Scripts {
		thisString += scriptToXML(script)
	}
	thisString += "</port>\n"
	return thisString
}

func ContinueXML(result g.Output) {
	thisOutput := ""
	thisOutput += fmt.Sprintf(`<host starttime="%d" endtime="%d"><status state="up" reason="syn-ack" reason_ttl="0"/>
<address addr="%s" addrtype="ipv4"/>
<hostnames>
`, result.Start.Unix(), result.End.Unix(), result.IP)
	for _, hostname := range result.Hostnames {
		thisOutput += fmt.Sprintf("<hostname name=\"%s\" type=\"PTR\"/>\n", xmlEscapeAttr(hostname))
	}
	if result.UHostname != "" {
		thisOutput += fmt.Sprintf("<hostname name=\"%s\" type=\"user\"/>\n", xmlEscapeAttr(result.UHostname))
	}
	thisOutput += "</hostnames>\n<ports>"
	for _, port := range result.Ports {
		thisOutput += portToXML(port, result)
	}
	thisOutput += "</ports>"
	if len(result.Scripts) != 0 {
		thisOutput += "\n<hostscript>"
		for _, script := range result.Scripts {
			thisOutput += scriptToXML(script)
		}
		thisOutput += "</hostscript>"
	}
	thisOutput += "\n<times srtt=\"247120\" rttvar=\"185695\" to=\"989900\"/>\n</host>\n"
	Write(thisOutput, g.XmlFilename, openedXmlFile)
}

func EndXML() {
	timestr := ConvertTime(g.ScanEndTime, "nmap-file")
	elapsed := fmt.Sprintf("%.2f", g.ScanEndTime.Sub(g.ScanStartTime).Seconds())
	addressWord := "address"
	hostWord := "host"
	if g.TotalHosts != 1 {
		addressWord = "addresses"
	}
	if g.AliveHosts != 1 {
		hostWord = "hosts"
	}
	Write(fmt.Sprintf(`<runstats><finished time="%d" timestr="%s" elapsed="%s" summary="Nmap done at %s; %d IP %s (%d %s up) scanned in %s seconds" exit="success"/><hosts up="%d" down="%d" total="%d"/>
</runstats>
</nmaprun>
`, g.ScanEndTime.Unix(), timestr, elapsed, timestr, g.TotalHosts, addressWord, g.AliveHosts, hostWord, elapsed, g.AliveHosts, g.TotalHosts-g.AliveHosts, g.TotalHosts), g.XmlFilename, openedXmlFile)
	CloseFile(openedXmlFile)
}
